<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Index/account')}" >账号列表</a>|					<a href="javascript:void(0);"  onclick="window.top.artiframe('{pigcms{:U('Index/admin',array('area_id'=>$_GET['area_id']))}','添加管理账号',500,450,true,false,false,addbtn,'add',true);">添加管理员</a>|					<a href="{pigcms{:U('Index/authority_group')}" >权限套餐</a>					<if condition="$config.open_juhepay eq 1">|<a href="{pigcms{:U('Index/salesman_list')}" class="on">业务员流水</a></if>				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td>						<form action="{pigcms{:U('Index/admin_money_list')}" method="get">							<input type="hidden" name="c" value="Index"/>							<input type="hidden" name="a" value="admin_money_list"/>							筛选: <input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>							<select name="searchtype">								<option value="admin_id" <if condition="$_GET['searchtype'] eq 'admin_id'">selected="selected"</if>>业务员ID</option>								<option value="realname" <if condition="$_GET['searchtype'] eq 'realname'">selected="selected"</if>>业务员昵称</option>								<option value="phone" <if condition="$_GET['searchtype'] eq 'phone'">selected="selected"</if>>手机号</option>							</select>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;							<input type="hidden" name="area_type" value="{pigcms{$_GET['type']}"/>							<input type="hidden" name="pid" value="{pigcms{$_GET['pid']}"/>							<input type="submit" style="margin-right:20px;" value="查询" class="button"/>						商家流水总额：{pigcms{$all_money|floatval}{pigcms{$config['Currency_txt']}						<a  href="javascript:void(0)" onclick="exports()" class="button" style="margin-right: 10px;">导出</a>						</form>					</td>				</tr>			</table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<col width="180" align="center"/>						</colgroup>						<thead>							<tr>								<th><a href="{pigcms{:U('User/index',array('sort'=>'uid'))}" style="color:blue;">ID</a></th>								<th>业务员名称</th>								<th>区域</th>								<th>手机号</th>								<th class="textcenter">商家流水总额</th>								<th class="textcenter">推广商家</th>														</tr>						</thead>						<tbody>							<if condition="is_array($admin_list)">								<volist name="admin_list" id="vo">									<tr>										<td>{pigcms{$vo.id}</td>										<td>{pigcms{$vo.realname}</td>										<td><php>if($vo['level']==1){</php><if condition="$vo.area_id gt 0 AND $vo.area_ip_desc neq ''">{pigcms{$vo.area_ip_desc}<elseif condition="in_array($vo['area_id'],$direct_city)" />{pigcms{$vo.area_name}市<elseif condition="in_array($vo['area_id'],$special_city)" />{pigcms{$vo.area_name}<else />{pigcms{$vo.area_name}省</if><php>}</php></td>										<td>{pigcms{$vo.phone}</td>										<td class="textcenter">{pigcms{$config['Currency_symbol']}{pigcms{$vo.spread_money|floatval=###}</td>										<td class="textcenter">										共{pigcms{$vo.spread_count|intval}个 &nbsp;&nbsp;&nbsp;<a href="{pigcms{:U('Index/admin_spread_merchant')}&invit_code={pigcms{$vo.invit_code}" >查看商家</a>										</td>																			</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="6">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="6">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div>		<script>		 var url = "{pigcms{$config.site_url}"		var export_url = "{pigcms{:U('Index/admin_money_list_export')}"</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><include file="Public:footer"/>